# -*- coding: utf-8 -*-
"""P6：投稿自检（**双盲 + 必备章节 + 篇幅估计**），只读稿件、只写一份 JSON。

为什么需要它：DAC 明说"投稿即终稿，deadline 后没有补救机会"。
本脚本把**能机械检查的都检查掉**，把**不能机械检查的（篇幅、图版）如实标成估计/待办**：
  * 双盲：作者名/单位/邮箱/致谢/仓库路径/机器名/内部文件名 逐项扫；
  * 必备：`Content Generated by AI` 章节、`References` 章节、无作者块、`Index Terms`；
  * 篇幅：按"双栏 IEEE 版式"给**区间估计**（本机**没有** LaTeX/pandoc ⇒ 无法编译，必须实测）；
  * 引用：`[1]–[10]` 全部在参考文献表里有对应条目（不许有悬空引用）；
  * 图：磁盘上有 1–5 号图，但正文**尚未插图** ⇒ 明确列为待办（用户已指示本轮不改图）。
产物：`work/runs/eda64-20261010/p6_paper/SUBMISSION_SELFCHECK.json`。
"""
from __future__ import annotations

import io
import json
import pathlib
import re
import sys
import time

sys.stdout.reconfigure(encoding="utf-8", errors="replace")
REPO = pathlib.Path(__file__).resolve().parents[2]
#: 目标稿件可用 `--doc <path>` 覆盖（默认仍是 v2；v3 由 `make_dac2027_en_v3.py` 生成）
_POS = [a for a in sys.argv[1:] if not a.startswith("-")]
V2 = (pathlib.Path(_POS[0]).resolve() if _POS
      else REPO / "docs/PAPER_DAC2027_EN_v2_20261011.md")
PROV = (V2.parent / (V2.name.replace("_20261011.md", "_PROVENANCE.md"))
        if _POS else REPO / "docs/PAPER_DAC2027_EN_v2_PROVENANCE.md")
FIGDIR = REPO / "work/runs/eda64-20261010/n5_figures"
OUT = REPO / "work/runs/eda64-20261010/p6_paper"

# 双盲扫描：出现即**报警**（人工判断是否真的泄身份）
LEAK_PATTERNS = {
    "email": r"[\w\.\-]+@[\w\.\-]+\.\w+",
    "affiliation_words": r"\b(University|Universität|Institute of Technology|Laboratory of|Dept\. of|Department of|College of)\b",
    "acknowledgement": r"\b(Acknowledge?ments?|We thank|This work was supported by|grant (no|number))\b",
    "repo_path": r"(work[/\\]runs|docs/|src/memsharness|\.venv)",
    "internal_file": r"\b[A-Za-z0-9_\-]+\.(mph|json|csv|jsonl|npz|py|java|duckdb)\b",
    "host_name": r"\b(node0\d|ubuntu-\d|DESKTOP-|C:\\\\Users)\b",
    "internal_tag": r"\[(?!\d+\])(?=[A-Za-z])[A-Za-z][A-Za-z0-9\-]*\]",
    "self_citation_phrase": r"\b(our (previous|earlier) work|in our prior|we previously (showed|proposed))\b",
    "state_field": r"\b(release_allowed|solver_spec|approved_solver|physics_consistent|solver_certified)\b",
    "sha256_literal": r"\b(?=[0-9a-f]*[a-f])[0-9a-f]{16,}\b",  # 必须含 a–f 字母，避免把 18 位小数误报
    "cjk_characters": r"[\u3000-\u303f\u4e00-\u9fff\uff00-\uffef]",  # 投稿件必须纯英文（实测抓到过中文残留）
}

REQUIRED = {
    "ai_section": r"^## Content Generated by AI\s*$",
    "references_section": r"^## References\s*$",
    "index_terms": r"\*\*Index Terms\*\*",
    "abstract_heading": r"^## Abstract\s*$",
    "no_author_block": None,   # 见下方专门检查
}


def main() -> int:
    OUT.mkdir(parents=True, exist_ok=True)
    text = V2.read_text(encoding="utf-8")
    lines = text.split("\n")
    body_cut = next(i for i, l in enumerate(lines) if l.startswith("## Content Generated by AI"))
    body = "\n".join(lines[:body_cut])
    refs = "\n".join(lines[body_cut:])

    def words(s):
        return len(re.findall(r"[A-Za-z0-9][A-Za-z0-9'’\-\./%]*", s))

    out: dict = {"kind": "p6_submission_selfcheck", "generated": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
                 "target": str(V2.relative_to(REPO)),
                 "sha256": __import__("hashlib").sha256(V2.read_bytes()).hexdigest()}

    # 1) 双盲
    leaks = {}
    for name, pat in LEAK_PATTERNS.items():
        hits = sorted(set(re.findall(pat, body, re.M)))
        if hits:
            leaks[name] = hits[:12]
    out["blind_check"] = {
        "patterns": list(LEAK_PATTERNS), "flagged": leaks,
        "verdict": ("clean" if not leaks else "review_flagged_patterns"),
        "note": ("命中不等于泄漏（如 '96-core server' 属基础设施描述）；但**内部字段名/仓库路径/"
                 "内部标签/sha256 一律不得出现** —— 本脚本对这几类零容忍。"),
        "tolerance": ["author block", "affiliations", "emails", "acknowledgements",
                      "self-identifying machine paths"],
    }
    # 作者块：标题后到 Abstract 之前只应有标题与状态引用块
    head = "\n".join(lines[: next(i for i, l in enumerate(lines) if l.startswith("## Abstract"))])
    out["blind_check"]["author_block_present"] = bool(
        re.search(r"^\s*(Author|Authors|by [A-Z][a-z]+ [A-Z])", head, re.M))

    # 2) 必备章节
    out["required_sections"] = {k: (bool(re.search(p, text, re.M)) if p else None)
                                for k, p in REQUIRED.items()}
    out["required_sections"]["ai_section_names_llm"] = bool(
        re.search(r"deepseek[- ]?v4|DeepSeek Harness", text, re.I))
    out["required_sections"]["ai_section_scope_stated"] = bool(
        re.search(r"assistance covered|Its assistance", text, re.I))

    # 3) 引用闭合
    cited = sorted({int(m) for m in re.findall(r"\[(\d+)\]", body)})
    listed = sorted({int(m) for m in re.findall(r"^\[(\d+)\]", refs, re.M)})
    out["citations"] = {"cited_in_body": cited, "listed_in_references": listed,
                        "dangling": [c for c in cited if c not in listed],
                        "uncited": [c for c in listed if c not in cited],
                        "closed": set(cited) <= set(listed)}

    # 4) 摘要词数
    ab = re.search(r"## Abstract\s*\n(.*?)\n\*\*Index Terms", text, re.S)
    out["abstract"] = {"words": words(ab.group(1)) if ab else None,
                       "manuscript_limit": 150,
                       "registration_target": "~100 words (Stage-1 form)",
                       "registration_in_provenance": bool(
                           PROV.is_file() and "Stage-1 注册摘要" in PROV.read_text(encoding="utf-8"))}

    # 5) 篇幅估计（**估计，不是实测**）
    body_words = words(body)
    refs_words = words(refs)
    out["length_estimate"] = {
        "body_words": body_words, "references_words": refs_words,
        "tables": len(re.findall(r"^\|---", body, re.M)),
        "figures_on_disk": sorted(p.name for p in FIGDIR.glob("fig*.*")),
        "figures_embedded_in_text": len(re.findall(r"!\[", body)),
        "method": ("按双栏 IEEE 版式**区间估计**：正文约 950–1100 词/页（含表与图占位）⇒ "
                   "6 页 ≈ 5,700–6,600 词当量"),
        "verdict_estimate": ("likely_fits_but_unverified" if body_words <= 5600
                             else "likely_over_6_pages"),
        "cannot_be_verified_here": ("本机**没有** LaTeX/pandoc/libreoffice ⇒ **无法编译**；"
                                    "必须用会议模板实测页数后再定稿（不得把估计当实测）"),
    }
    out["figures_to_do"] = {"embedded": False,
                            "why": "用户 2026-10-10 指示「图片先不需要你修改」⇒ 本轮不动图；"
                                   "投稿前需把 fig1–fig5 按目标版式插入并核对图注数字"}

    (OUT / ("SUBMISSION_SELFCHECK_%s.json" % V2.stem)).write_text(
        json.dumps(out, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("== 双盲：%s" % out["blind_check"]["verdict"])
    for k, v in leaks.items():
        print("   ⚠ %-18s %s" % (k, v))
    print("== 必备章节：%s" % out["required_sections"])
    print("== 引用：[cited %d / listed %d] 悬空=%s 未引=%s"
          % (len(cited), len(listed), out["citations"]["dangling"], out["citations"]["uncited"]))
    print("== 摘要：%d 词（稿内上限 %d）" % (out["abstract"]["words"], 150))
    print("== 篇幅：正文 %d 词 / 参考 %d 词 / 表 %d / 图(磁盘 %d, 正文 %d) ⇒ %s"
          % (body_words, refs_words, out["length_estimate"]["tables"],
             len(out["length_estimate"]["figures_on_disk"]),
             out["length_estimate"]["figures_embedded_in_text"],
             out["length_estimate"]["verdict_estimate"]))
    print("== 写出", OUT / ("SUBMISSION_SELFCHECK_%s.json" % V2.stem))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
